quests[28741] = { id = 28741, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ascendant Lord Obsidius", description = "<Pip's helm buzzes.>\n\nGOOD GOLLY! Look at this place! A... Are those Deathwing's claw marks on the ceiling?! And what's that creature in the center of the chamber?\n\nI don't see Raz anywhere. Let's take care of this monster and find Raz!", progress = "<Pip's helm crackles with static.>", completion = "Poor Raz. He was the best friend a gnome ever had. At least we avenged his death and cleared out this hellish cavern!", objectives = "Kill Ascendant Lord Obsidius.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28742] = { id = 28742, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shy-Rotam", description = "Time for the big kill, pal! Shy-Rotam lurks in the north, the largest frostsaber of them all.\n\nYou should feel honored. There's no fiercer game for a hunter to match their skills against... and if you saw the cash I'm being offered by gourmands that want a piece of this fellow, your eyes would pop out!\n\nOnce you've got her, head on back to camp. Don't want to totally exhaust our frostsaber population in one day...", progress = "Shy-Rotam's in the north. No food 'til you finish!", completion = "Amazing, kid. You're a cut above! I went through about five different contracted hunters trying to get that cat.\n\nWell, we found two of them after the Captain got the corpse, but let's not dwell on that...", objectives = "Slay Shy-Rotam.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28743] = { id = 28743, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tailgunner!", description = "You up for a little hunting, {name}?\n\nHop in! I'll fly, you shoot!", sourceObjective = "Shoot down 15 Schnottz Aces.", sourceObjectiveStatus = "unverified-source-field" }
quests[28744] = { id = 28744, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ghouls Hate My Grains", description = "You're a pro at this, {name}! A regular junior botanist! Listen, I've got a new seed to try called the rocknut. Use it to block the undead. Just drop it down and they'll stop dead in their tracks. Undead are so stupid!\n\nLet's give it a try!", completion = "I think that made Stillwater angry. He's sending the heavy-hitters after us now. No time to lose, friend, let's go!", objectives = "Survive 2 Massive Waves of Zombies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28745] = { id = 28745, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Screechy Keen", description = "Them smaller owls are sure tasty, but Goodgrub says there's even bigger ones further south. Screechers, the folk around here call 'em... they make a heck of a noise when you tussle with them!\n\nBut he says they're the best owls he's ever tasted or sold, and I believe him. Why don't you go rustle up some of those for us while I keep arguin' with Francis here?", objectives = "Slay 15 Winterspring Screechers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28746] = { id = 28746, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Penetrating Their Defenses", description = "Here we go, {name}!\n\nJust beyond that door lies the control room.\n\nI'll just run in, disable the reorigination mechanism, and then we all go home. Nice an' easy.\n\nYe see, <lad/lass>, it's this level of preparation that separates yer true archaeologist from yer average treasure hunter.\n\nNo sense in stirring up the beasties if ye don't have to. Just makes a mess a' things...", progress = "What is it, {name}?", completion = "Well, I've got bad news and I've got...\n\nNo, scratch that. There only be bad news.", objectives = "Gain entry to the Titan Control Room.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28747] = { id = 28747, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Someone Setup the Pumpkin Bomb", description = "You ever seen one of these?\n\n<Brazie pulls out a pumpkin.>\n\nThis ain't no ordinary pumpkin, friend. See, once you plant it they'll lay in wait until a zombie shows up and then KABLOOEY! Zombie guts all over the place. Let's go!", completion = "D... Do you hear that rumblin'? I think Stillwater is comin'! HOLY MOLY LOOK OUT!", objectives = "Survive 2 Massive Waves of Zombies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28748] = { id = 28748, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lawn of the Dead", description = "IT'S STILLWATER! HE'S ALMOST HERE! It's going to take everything that we've got to beat him! Let's do this!", completion = "I can't believe we defeated him, {name}! That was the toughest fight yet, but there are still hundreds of crazed zombies roaming around Hillsbrad. We'll need to stay alert.", objectives = "Defeat Warden Stillwater.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28749] = { id = 28749, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle for Andorhal", description = "We just received a gryphon from the plaguelands, bearing news.  It doesn't sound good.\n\nThe city of Andorhal is in the middle of a three-way war between the Forsaken, the Alliance, and the Scourge.  King Wrynn has rolled the dice and sent a death knight to lead the charge for his cause, but I'm sure he can use all the help he can get.\n\nThey specifically asked for an Alliance {class} to participate in some specialized missions.  If you accept the charge, speak to me again and I will prepare a portal.", completion = "It's about time you arrived, {class}.", objectives = "Speak with War-Mage Erallier to be teleported to Andorhal in Western Plaguelands. Then report to Thassarian within Andorhal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28750] = { id = 28750, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Battle for Andorhal", description = "We just received a windrider from the plaguelands, bearing news.  It doesn't sound good.\n\nThe city of Andorhal is in the middle of a three-way war between the Forsaken, the Alliance, and the Scourge.  It sounds like Sylvanas has made her move, and to make matters interesting, she's put Koltira Deathweaver, the death knight, in command.\n\nThey specifically asked for a Horde {class} to participate in some specialized missions.  If you accept the charge, speak to me again and I will prepare a portal.", completion = "It's about time you arrived, {class}.", objectives = "Speak with Arcanist Arman to be teleported to Andorhal, in the Western Plaguelands. Then report to Koltira Deathweaver within Andorhal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28751] = { id = 28751, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tending the Garden", description = "Even though we beat Warden Stillwater, his zombies still roam the countryside. Look there, another wave is approaching! Help me fight them off, old buddy! Let's go!", completion = "That'll keep 'em out for today, but I know they'll be back tomorrow. Hopefully you'll be around to help me.", objectives = "Survive 2 Massive Waves of Zombies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28752] = { id = 28752, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unstoppable Onslaught", description = "See how long you can last! Hold off at least 10 waves and I'll give you some coin." }
quests[28753] = { id = 28753, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doing it the Hard Way", description = "Blast it all!\n\nSomeone's gone and corrupted the entire system! There be no way fer me ta access the main repository from this console.\n\nWe're gunna hafta do this the hard way, <lad/lass>. I hope you an' yer friends here are up to a fight.\n\nThere be four guardians on the upper level of this place. I won't be able ta utilize these discs 'til they be... uhh, offline, shall we say.", completion = "Arrite, then.\n\nLet's deposit these discs and be done with this!", objectives = "Brann Bronzebeard wants you to kill Isiset, Ammunae, Setesh, and Rajh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28754] = { id = 28754, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle of Life and Death", description = "Alexstrasza has been preparing this site for many years. Once Deathwing is lured into this circle, she will use the rejuvenating powers of its life energy to overwhelm and destroy him.\n\nIt is important that the five lifebinder stones that surround this circle remain uncorrupted during the fight. Deathwing will be concentrating solely on the Queen of Dragons herself; you may escape his notice. Kill any of his minions that try to corrupt the circle.\n\nTalk to me when you are ready to begin!", objectives = "Help Alexstrasza try to kill Deathwing. Protect the five Lifebinder Stones that surround the circle!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28755] = { id = 28755, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Annals of the Silver Hand", description = "Do you know who the Knights of the Silver Hand were? They were the original paladins of the Light, and from their ranks came knights who would later join the Argent Dawn or the Scarlet Crusade. Though many have gone astray, they still possess valuable relics of the Silver Hand.\n\nDeep in Stratholme, under the watchful eye of Instructor Galford, volumes of the Annals of the Silver Hand survive. Any volumes you could recover would be a fitting addition to the rededicated Light's Hope Chapel.", progress = "Have you recovered any of the lost histories of the Silver Hand?", completion = "This is indeed one of the lost volumes! Tyrosus will be most pleased when he learns of your find.", objectives = "Recover a lost volume of the Annals of the Silver Hand from Stratholme.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28756] = { id = 28756, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aberrations of Bone", description = "In life, my brothers and I fought against all the forces of the Scourge, but none were so reviled as the necromancers. It was not enough for them raise our dead comrades and send them against us; no, they created twisted golems of bone with scythes for hands.\n\nThese aberrations slew many of my brothers, and yet we could not destroy them all. I ask you, {name}, to carry on the task of the fallen. Venture into the Ossuary of Scholomance and slay the largest and most dangerous of these abominable creatures.", progress = "Have you carried on our fight against the remnants of the Scourge in these lands?", completion = "Your deeds do honor to those who fell in battle defending this hallowed ground.", objectives = "Kill Rattlegore in the Ossuary of Scholomance.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28757] = { id = 28757, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beating Them Back!", description = "So you're the new recruit from Stormwind, eh? I'm Marshal McBride, commander of this garrison. Glad to have you on board...\n\n<McBride looks through some papers.>\n\n{name}. It is {name}, right?\n\nYou've arrived just in time. The Blackrock orcs have managed to sneak into Northshire through a break in the mountain. My soldiers are doing the best that they can to push them back, but I fear they will be overwhelmed soon.\n\nHead northwest into the forest and kill the attacking Blackrock worgs! Help my soldiers!", progress = "Have you beaten back the Blackrock worgs?", completion = "You've bought us a little time, {name}, but we've got even bigger problems to deal with now.", objectives = "Kill 6 Blackrock Worgs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28758] = { id = 28758, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Battle of Life and Death", description = "Alexstrasza and Deathwing have taken into the skies over Grim Batol! Her plan unravels - the Dragon Queen is outside the Circle of Life she prepared earlier. We'll need to support her with everything we've got.\n\nHurry! Climb aboard one of the Vermillion Vanguard behind me.\n\nIf we find any Twilight Drakes aiding Deathwing, we will need to kill them off. Mount up, quickly!", completion = "Thanks to your quick action, the Dragon Queen still lives. She is being brought back to Wyrmrest to recover.\n\nBut the battle wasn't a complete failure. Deathwing was gravely wounded. I suspect he will go into hiding to recuperate. Alexstrasza has bought us time to strike!", objectives = "Mount a Vermillion Vanguard. Slay 8 Twilight Shadowdrakes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28759] = { id = 28759, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lions for Lambs", description = "The invading orcs aren't fools. They are sizing us up, making sure that when they attack it will be to their advantage.\n\nIn the forest, to the northwest, are Blackrock spies. They peer at us through spyglasses, watching our every move - waiting. I want you take the fight to them!\n\nKill the Blackrock spies! We must show them that we know they are watching us and that we are prepared!", progress = "Kill the spies!", completion = "Excellent work, {name}. You've turned out to be quite an asset to this garrison. It's time for you to train!", objectives = "Kill 8 Blackrock Spies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28760] = { id = 28760, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vengeance for Orsis", description = "The great city of Orsis was attacked by the armies of air.\n\nWe were taken prisoner.  We were the lucky ones.\n\nMost died, trapped beneath the choking desert sands.\n\nAsaad, Al'Akir's caliph, ordered the attack... and he must pay with his life.", completion = "Blessings upon you.  Please accept this as a token of my gratitude.", objectives = "Slay Asaad.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28761] = { id = 28761, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor the Flame" }
quests[28762] = { id = 28762, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beating Them Back!", description = "So you're the new recruit from Stormwind, eh? I'm Marshal McBride, commander of this garrison. Glad to have you on board...\n\n<McBride looks through some papers.>\n\n{name}. It is {name}, right?\n\nYou've arrived just in time. The Blackrock orcs have managed to sneak into Northshire through a break in the mountain. My soldiers are doing the best that they can to push them back, but I fear they will be overwhelmed soon.\n\nHead northwest into the forest and kill the attacking Blackrock worgs! Help my soldiers!", progress = "Have you beaten back the Blackrock worgs?", completion = "You've bought us a little time, {name}, but we've got even bigger problems to deal with now.", objectives = "Kill 6 Blackrock Worgs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28763] = { id = 28763, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beating Them Back!", description = "So you're the new recruit from Stormwind, eh? I'm Marshal McBride, commander of this garrison. Glad to have you on board...\n\n<McBride looks through some papers.>\n\n{name}. It is {name}, right?\n\nYou've arrived just in time. The Blackrock orcs have managed to sneak into Northshire through a break in the mountain. My soldiers are doing the best that they can to push them back, but I fear they will be overwhelmed soon.\n\nHead northwest into the forest and kill the attacking Blackrock worgs! Help my soldiers!", progress = "Have you beaten back the Blackrock worgs?", completion = "You've bought us a little time, {name}, but we've got even bigger problems to deal with now.", objectives = "Kill 6 Blackrock Worgs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
