quests[28766] = { id = 28766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beating Them Back!", description = "So you're the new recruit from Stormwind, eh? I'm Marshal McBride, commander of this garrison. Glad to have you on board...\n\n<McBride looks through some papers.>\n\n{name}. It is {name}, right?\n\nYou've arrived just in time. The Blackrock orcs have managed to sneak into Northshire through a break in the mountain. My soldiers are doing the best that they can to push them back, but I fear they will be overwhelmed soon.\n\nHead northwest into the forest and kill the attacking Blackrock worgs! Help my soldiers!", progress = "Have you beaten back the Blackrock worgs?", completion = "You've bought us a little time, {name}, but we've got even bigger problems to deal with now.", objectives = "Kill 6 Blackrock Worgs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28767] = { id = 28767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beating Them Back!", description = "So you're the new recruit from Stormwind, eh? I'm Marshal McBride, commander of this garrison. Glad to have you on board...\n\n<McBride looks through some papers.>\n\n{name}. It is {name}, right?\n\nYou've arrived just in time. The Blackrock orcs have managed to sneak into Northshire through a break in the mountain. My soldiers are doing the best that they can to push them back, but I fear they will be overwhelmed soon.\n\nHead northwest into the forest and kill the attacking Blackrock worgs! Help my soldiers!", progress = "Have you beaten back the Blackrock worgs?", completion = "You've bought us a little time, {name}, but we've got even bigger problems to deal with now.", objectives = "Kill 6 Blackrock Worgs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28768] = { id = 28768, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winterspring!", description = "Donova Snowden, dwarf woman, is friend of the Timbermaw.\n\nWe trade firewater.\n\nShe is at Frostfire Hotsprings, to the east, through our cave.\n\nShe needs help to beat up the Winterfall furbolg.  Maybe you will help her.", completion = "Thank goodness you're here. I've discovered the secret of the fierce Winterfall furbolg.", objectives = "Report to Donova Snowden at Frostfire Hot Springs in Winterspring.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28769] = { id = 28769, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lions for Lambs", description = "The invading orcs aren't fools. They are sizing us up, making sure that when they attack it will be to their advantage.\n\nIn the forest, to the northwest, are Blackrock spies. They peer at us through spyglasses, watching our every move - waiting. I want you take the fight to them!\n\nKill the Blackrock spies! We must show them that we know they are watching us and that we are prepared!", progress = "Kill the spies!", completion = "Excellent work, {name}. You've turned out to be quite an asset to this garrison. It's time for you to train!", objectives = "Kill 8 Blackrock Spies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
