quests[28790] = { id = 28790, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Personal Summons", description = "<An unfamiliar feeling wells up from deep within you, flooding your mind with thoughts and images.>\n\nHear my words, {name}.\n\nOur world finds itself in the grip of a terrible crisis.\n\nI call upon you to lend your aid in this desperate hour.\n\nI am Krogar.\n\nSeek me out at once, and your destiny shall be revealed.\n\nYou can find me north of the Drag in Orgrimmar.", completion = "May your sense of honor and duty serve Azeroth well, {class}.", objectives = "Farseer Krogar wants you to meet him in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28791] = { id = 28791, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Sent Assassins", description = "Have you ever seen a goblin, {name}? They're wretched little monsters that love only two things: gold and themselves.\n\nThe Blackrock orcs have enlisted the aid of goblin assassins to kill our soldiers. If you look to the field in the north you can barely make out their silhouettes, sneaking about in the grass.\n\nI need you to head out there and kill every goblin that you see. They need to learn that nobody messes with the Alliance!", completion = "That will teach those monsters! They'll think twice before taking another mercenary job for orcs.", objectives = "Kill 8 Goblin Assassins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28792] = { id = 28792, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Sent Assassins", description = "Have you ever seen a goblin, {name}? They're wretched little monsters that love only two things: gold and themselves.\n\nThe Blackrock orcs have enlisted the aid of goblin assassins to kill our soldiers. If you look to the field in the north you can barely make out their silhouettes, sneaking about in the grass.\n\nI need you to head out there and kill every goblin that you see. They need to learn that nobody messes with the Alliance!", completion = "That will teach those monsters! They'll think twice before taking another mercenary job for orcs.", objectives = "Kill 8 Goblin Assassins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
