quests[28814] = { id = 28814, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Followers and Leaders", description = "The documents detail the arrival of High Priestess Azil to the depths of the Stonecore.\n\nAzil is described as a high-ranking member of the Twilight Council.  Additionally, her entourage of over a hundred devout followers is preparing for an unholy ritual of unforeseen darkness.\n\nSounds like an event you need to put a stop to.", progress = "You've returned, {name}.  What news do you bring?", completion = "A high priestess, you say?  And a member of the Twilight Council?\n\nExcellent work.  I hope you find your rewards suitable.", objectives = "Slay High Priestess Azil and 101 Devout Followers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28815] = { id = 28815, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Twilight Documents", description = "We've tailed one of the Twilight's Hammer operatives here.  He goes by the name of Millhouse Manastorm.\n\nWe have reason to believe he's carrying important documents.\n\nThis is as far as we can safely go, however, without neglecting our duty to defend the Temple of Earth's inner perimeter.\n\nTrack down Manastorm and retrieve the documents from him.", progress = "These appear to be the right documents.", completion = "<You open the documents and look for any noteworthy information.>", objectives = "Obtain the Twilight Documents.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28816] = { id = 28816, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Depths", description = "The Earthen Ring has identified the watery realm of Vashj'ir as a source of the adversary's destructive energies.\n\nIt is still uncertain what dangers might be faced there. Any information you could gather would be of great value.\n\nThe Horde is sending warships to the region as we speak. To gain passage, speak to Commander Thorak at Bladefist Bay.\n\nMay the spirits guide you, {name}.", completion = "Lok'tar, brother! You have arrived just in time.", objectives = "Report to Commander Thorak at Bladefist Bay in Durotar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28817] = { id = 28817, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rear is Clear", description = "Excellent work, {name}! The rear is now officially clear. We'll take care of the stragglers. I want you to go back to Marshal McBride, standing in front of Northshire Abbey, south of here, and let him know that the goblin situation is under control.\n\nFarewell, {class}.", completion = "With your help we have managed to secure the northern and western sectors of Northshire. We still have a rather large contingency of Blackrock orcs to the east and they've begun burning down the forest!", objectives = "Report to Marshal McBride in front of Northshire Abbey in Elwynn Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28818] = { id = 28818, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rear is Clear", description = "Excellent work, {name}! The rear is now officially clear. We'll take care of the stragglers. I want you to go back to Marshal McBride, standing in front of Northshire Abbey, south of here, and let him know that the goblin situation is under control.\n\nFarewell, {class}.", completion = "With your help we have managed to secure the northern and western sectors of Northshire. We still have a rather large contingency of Blackrock orcs to the east and they've begun burning down the forest!", objectives = "Report to Marshal McBride in front of Northshire Abbey in Elwynn Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28819] = { id = 28819, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rear is Clear", description = "Excellent work, {name}! The rear is now officially clear. We'll take care of the stragglers. I want you to go back to Marshal McBride, standing in front of Northshire Abbey, south of here, and let him know that the goblin situation is under control.\n\nFarewell, {class}.", completion = "With your help we have managed to secure the northern and western sectors of Northshire. We still have a rather large contingency of Blackrock orcs to the east and they've begun burning down the forest!", objectives = "Report to Marshal McBride in front of Northshire Abbey in Elwynn Forest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
