quests[28909] = { id = 28909, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sauranok Will Point the Way", description = "I see you haven't yet spoken to the Warchiefs... other... advisor, Sauranok the Mystic. He has been at their side since our campaign together in Northrend.\n\nTo assault the Twilight Highlands, we're going to need a map of the shoreline. I have tasked Sauranok with digging up this information. See if he can use your assistance!", completion = "<Sauranok nods toward you.>\n\n{class}.", objectives = "Speak with Sauranok the Mystic at Grommash Hold in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
