quests[28934] = { id = 28934, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it looks like it's in the Uldum, just east of the Tomb of Khartut, close to the entrance from Tanaris. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya.", objectives = "Kill 5 Crown Technicians and use Snagglebolt's Khorium Bomb to destroy one chemical wagon east of the Tomb of Khartut in Uldum, then return to Inspector Snip Snagglebolt in Stormwind.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28935] = { id = 28935, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Crushing the Crown", description = "This ledger is full of locations, and I need you to investigate and take action, pal. This has gone on long enough.\n\nHere's an entry I want you to check out: it looks like it's in Uldum, east of the Tomb of Khartut and near the entrance from Tanaris. Get out there and rough 'em up.\n\nOh, and if you see something big and dangerous enough that it needs destroying, toss this bomb at it.", completion = "Good job, kid. You deserve a little somethin'. And hey, come back tomorrow if you get the time; I might have a job for ya.", objectives = "Kill 5 Crown Technicians and use Snagglebolt's Khorium Bomb to destroy one chemical wagon east of the Tomb of Khartut in Uldum, then return to Detective Snap Snagglebolt in Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28936] = { id = 28936, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diva Dilemma", description = "TBD.", objectives = "Kill 6 naga.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[28937] = { id = 28937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alliance Breadcrumb", description = "Monsters!  They were monsters I tell you!\n\n Our ship pulled into port just south of Stromgarde, but the coast there is infested with strange creatures. \n\n Other than seeing their ugly mugs and hearing strange gurgling noises, I didn't wait to find out what they wanted. You'd better go help my shipmates, {name}!", sourceObjective = "Talk to Lady Gurga in Faldir's Cove.", sourceObjectiveStatus = "unverified-source-field" }
